<?php

namespace App\Support;

use Illuminate\Support\Str;

class PolishWarningSignContentBuilder
{
    /**
     * @param  array{code: string, slug: string, name: string, primary_query: string}  $sign
     * @return array<string, mixed>
     */
    public function build(array $sign, int $index): array
    {
        $config = $this->warningConfig()[$sign['code']] ?? $this->fallbackConfig($sign);
        $assetKey = $sign['slug'];
        $assetPath = "traffic-signs/signs/warnings/{$assetKey}.webp";
        $imageAlt = "{$sign['code']} {$sign['name']}";

        return [
            'intro_definition' => "Znak {$sign['code']} ostrzega przed {$config['hazard']}. To sygnał, że kierowca powinien zareagować wcześniej niż zwykle i przygotować się na zmianę warunków jazdy.",
            'meaning' => $config['meaning'],
            'placement' => $config['placement'],
            'driver_behavior' => $config['behavior'],
            'legal_summary' => "To znak ostrzegawczy, więc sam z siebie nie wprowadza zakazu tak jak znaki z grupy B. W praktyce jednak {$sign['code']} podnosi wymagany poziom ostrożności: kierowca powinien odpowiednio wcześniej dostosować prędkość, tor jazdy i zakres obserwacji do zagrożenia widocznego na znaku.",
            'fine_summary' => "Największe ryzyko przy {$sign['code']} nie polega na \"minięciu znaku\", tylko na zbyt późnej reakcji na zagrożenie, przed którym ostrzega. Jeśli kierowca nie dostosuje zachowania do warunków, łatwo dochodzi tu do błędu ocenianego przez pryzmat niedostosowania prędkości, braku ostrożności albo naruszenia pierwszeństwa.",
            'common_mistakes' => $config['mistake'],
            'editorial_notes' => $config['editorial_notes'],
            'review_notes' => 'Szkic merytoryczny przygotowany dla pełnego pokrycia kategorii znaków ostrzegawczych. Przed publikacją zrobić pass redakcyjny na przykładach sytuacyjnych i na różnicach wobec podobnych znaków z grupy A.',
            'source_notes' => 'Treść bazowa przygotowana na podstawie urzędowego wykazu znaków ostrzegawczych i praktyki szkolenia kierowców. Przed publikacją potwierdzić finalny wording, przykłady ruchowe i ewentualne powiązania z tabliczkami lub oznakowaniem towarzyszącym.',
            'faq_items' => [
                [
                    'question' => "Na co znak {$sign['code']} każe przygotować się kierowcy?",
                    'answer' => $config['faq_preparation'],
                ],
                [
                    'question' => "Jaki błąd najczęściej pojawia się przy znaku {$sign['code']}?",
                    'answer' => $config['faq_mistake'],
                ],
            ],
            'meta_title' => "{$sign['code']} {$sign['name']} - znaczenie, zagrożenie i zachowanie kierowcy",
            'meta_description' => "Sprawdź, co oznacza znak {$sign['code']} {$sign['name']}, gdzie najczęściej występuje i jak przygotować reakcję kierowcy przed miejscem zagrożenia.",
            'image_path' => $assetPath,
            'image_alt' => $imageAlt,
            'image_width' => 1200,
            'image_height' => 1200,
            'og_image_path' => $assetPath,
            'og_image_alt' => $imageAlt,
            'og_image_width' => 1200,
            'og_image_height' => 1200,
