    /**
     * @param  array{code: string, slug: string, name: string, primary_query: string}  $sign
     * @return array{hazard: string, meaning: string, placement: string, behavior: string, mistake: string, faq_preparation: string, faq_mistake: string, editorial_notes: string}
     */
    protected function fallbackConfig(array $sign): array
    {
        $lowerName = Str::of($sign['name'])->lcfirst()->toString();

        return [
            'hazard' => $lowerName,
            'meaning' => "Znak {$sign['code']} uprzedza o zagrożeniu opisanym jako {$lowerName}. Kierowca powinien odpowiednio wcześniej przygotować obserwację i zmienić styl jazdy pod warunki za znakiem.",
            'placement' => 'Najczęściej taki znak pojawia się przed miejscem, w którym zmiana warunków ruchu nie byłaby wystarczająco czytelna bez wcześniejszego ostrzeżenia.',
            'behavior' => 'Po zauważeniu znaku ogranicz prędkość, poszerz obserwację otoczenia i nie zostawiaj decyzji o reakcji na ostatni moment.',
            'mistake' => 'Najczęstszy błąd to potraktowanie znaku ostrzegawczego jak neutralnej informacji, bez realnej zmiany prędkości lub zakresu obserwacji.',
            'faq_preparation' => 'Na miejsce, które wymaga wcześniejszego przygotowania obserwacji i tempa jazdy.',
            'faq_mistake' => 'Kierowcy najczęściej reagują zbyt późno i dopiero przy samym zagrożeniu próbują skorygować prędkość lub tor jazdy.',
            'editorial_notes' => 'Przed publikacją doprecyzować przykład praktyczny i podobne znaki z tej rodziny.',
        ];
    }
